package scheduler

import("context";"errors";"fmt";"sort";"strings";"github.com/example-user/runnerhub/internal/core";"github.com/example-user/runnerhub/internal/store")
var ErrNoCapacity=errors.New("no compatible host capacity")
type Decision struct{Host core.Host `json:"host"`;Reason string `json:"reason"`;Used core.Resources `json:"used"`};type Scheduler struct{Store store.Store}
func(s Scheduler)SelectHost(ctx context.Context,pool core.RunnerPool)(Decision,error){hosts,err:=s.Store.ListHosts(ctx);if err!=nil{return Decision{},err};workers,err:=s.Store.ListWorkers(ctx);if err!=nil{return Decision{},err};used:=map[string]core.Resources{};poolActive:=0;for _,w:=range workers{if OccupiesHostResources(w.State){used[w.HostID]=core.Add(used[w.HostID],w.Resources)};if w.PoolID==pool.ID&&CountsTowardPoolConcurrency(w.State){poolActive++}};if poolActive>=pool.MaxConcurrency{return Decision{},fmt.Errorf("%w: pool concurrency exhausted (%d/%d)",ErrNoCapacity,poolActive,pool.MaxConcurrency)};type candidate struct{h core.Host;used core.Resources;score int64};var candidates []candidate;var rejects []string;for _,h:=range hosts{if reason:=HostRejectionReason(h,pool,used[h.ID]);reason!=""{rejects=append(rejects,h.Name+": "+reason);continue};u:=used[h.ID];score:=(h.Capacity.CPUMillis-u.CPUMillis-pool.Resources.CPUMillis)+(h.Capacity.MemoryBytes-u.MemoryBytes-pool.Resources.MemoryBytes)/(1024*1024);candidates=append(candidates,candidate{h:h,used:u,score:score})};if len(candidates)==0{return Decision{},fmt.Errorf("%w: %s",ErrNoCapacity,strings.Join(rejects,"; "))};sort.SliceStable(candidates,func(i,j int)bool{return candidates[i].score>candidates[j].score});c:=candidates[0];return Decision{Host:c.h,Used:c.used,Reason:"best compatible online host with available requested capacity"},nil}
func CountsTowardPoolConcurrency(s core.WorkerState)bool{switch s{case core.WorkerRequested,core.WorkerProvisioning,core.WorkerStarting,core.WorkerRegistering,core.WorkerReady,core.WorkerBusy:return true;default:return false}}
func OccupiesHostResources(s core.WorkerState)bool{return s!=core.WorkerDeleted}
func HostRejectionReason(h core.Host,pool core.RunnerPool,used core.Resources)string{if h.State!=core.HostOnline{return "not online"};if !matchTags(h.Tags,pool.HostSelector){return "selector mismatch"};if !supportsIsolation(h,pool.Isolation){return "isolation unsupported"};if !core.Fits(h.Capacity,used,pool.Resources){return "resources exhausted"};return ""}
func matchTags(tags,sel map[string]string)bool{for k,v:=range sel{if tags[k]!=v{return false}};return true}
func supportsIsolation(h core.Host,mode core.IsolationMode)bool{if h.Tags==nil{return mode==core.IsolationContainerTrusted&&h.Provider=="docker"};key:="isolation."+string(mode);if v,ok:=h.Tags[key];ok{return v=="true"};return mode==core.IsolationContainerTrusted&&h.Provider=="docker"}
